<?php
$search=trim((string)($_GET['q']??''));$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$sql="SELECT t.*,c.full_name customer_name,u.name cashier_name FROM transactions t LEFT JOIN customers c ON c.id=t.customer_id LEFT JOIN users u ON u.id=t.cashier_id WHERE DATE(t.created_at) BETWEEN ? AND ?";$params=[$from,$to];if($search!==''){$sql.=' AND (t.transaction_code LIKE ? OR c.full_name LIKE ?)';$params[]="%$search%";$params[]="%$search%";}$sql.=' ORDER BY t.created_at DESC LIMIT 300';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['total'],$rows));
?>
<div class="page-heading"><div><div class="eyebrow">Sales ledger</div><h1>Transactions</h1><p>Search payments and open receipts for reprinting.</p></div><a href="<?=h(app_page_url('pos'))?>" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>New sale</a></div>
<div class="card"><div class="card-body border-bottom"><form class="row g-2 align-items-end"><input type="hidden" name="page" value="transactions"><div class="col-md-4"><label class="form-label">Search transaction / customer</label><input class="form-control" name="q" value="<?=h($search)?>" placeholder="Transaction number or customer"></div><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=h($from)?>"></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=h($to)?>"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100">Filter</button></div></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Transaction</th><th>Customer</th><th>Cashier</th><th>Payment</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows)echo table_empty(7);foreach($rows as $r):?><tr><td><strong><?=h($r['transaction_code'])?></strong><div class="small-muted"><?=date('M j, Y g:i A',strtotime($r['created_at']))?></div></td><td><?=h($r['customer_name']??'Guest / walk-in')?></td><td><?=h($r['cashier_name']??'—')?></td><td><?=h(strtoupper(str_replace('_',' ',$r['payment_method'])))?></td><td class="fw-bold"><?=money($r['total'])?></td><td><?=status_badge($r['status'])?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('receipt',['id'=>$r['id']]))?>"><i class="bi bi-printer me-1"></i>Receipt</a></td></tr><?php endforeach;?></tbody></table></div><div class="card-body d-flex justify-content-between"><span class="small-muted"><?=count($rows)?> transaction(s) · showing up to 300</span><strong>Filtered total: <?=money($total)?></strong></div></div>
